-- Falcon MCP voice trace kit (format falcon-voice-trace-1). Generated by falcon_voice_trace_kit.
-- UVIScript / Lua 5.1. For development builds of YOUR instrument script only; remove before release.
--
-- 1. Paste this whole block at the TOP of the instrument script, before any code that copies
--    playNote/releaseVoice/postEvent/spawn into locals (a local copy made earlier is not traced).
-- 2. Add `FVT.install()` as the LAST line of the script, after onNote/onRelease/onEvent/onInit exist.
-- 3. Optionally report decisions where they are actually made:
--      FVT.legato(true, "overlap", {from=prev, to=e.note})   FVT.envelope(id, false, "legato glide")
--      FVT.pending("open", {id="handoff", note=e.note})       FVT.pending("commit"|"cancel"|"expire", {id="handoff"})
--      FVT.owner(auxId, "aux_wavetable")                      FVT.mark("phrase 2")
-- The kit records what THIS script does: the keys it receives, every playNote/postEvent/releaseVoice/
-- changeTune/fade call with the callback and key that made it, and the FVT.* reports. Events go to
-- an in-memory ring; a background task saves it as JSON every flush_ms of engine time. It never
-- changes what the script plays. Voices started by other scripts or by the engine are not seen.
local FVT_CONFIG = __FVT_CONFIG__

FVT = {format="falcon-voice-trace-1"}
do
    local cfg = FVT_CONFIG
    local cap = cfg.capacity
    local okJson, json = pcall(require, "uvi.json")
    local ring, head, count, seq, dropped = {}, 0, 0, 0, 0
    local dirty, saving, saveError, flushing = false, false, nil, false
    -- UVIScript has no coroutine library, so the context of the running callback or task is one
    -- variable: callbacks and spawned tasks set it on entry, and the wrapped wait*() calls restore the
    -- task's own context when it resumes.
    local current = {cb="script"}
    local inApi = false      -- Falcon's playNote/releaseVoice call the global postEvent: record once
    local held = {}          -- channel*128+note -> FIFO of key ids (kid)
    local nextKid, nextVoice = 0, 0
    local voiceKeys, voiceKeyCount = {}, 0   -- tostring(native id) -> trace voice number
    local raw = {}

    local function now()
        local ok, t = pcall(getTime)
        if ok and type(t) == "number" then return t end
        return nil
    end
    local function ctx() return current end
    local function setCtx(c) current = c end
    local function clean(value)
        local kind = type(value)
        if kind == "boolean" or kind == "string" and #value <= 200 then return value end
        if kind == "string" then return string.sub(value, 1, 200) end
        if kind == "number" and value == value and math.abs(value) < 1e100 then return value end
        if kind == "table" then
            local out = {}
            for i = 1, math.min(#value, 16) do
                local item = value[i]
                if type(item) == "number" or type(item) == "string" then out[#out + 1] = item end
            end
            return table.concat(out, ",")
        end
        return nil
    end

    local function record(kind, fields)
        if not cfg.enabled then return nil end
        local t = now()
        local c = ctx()
        local row = {}
        if fields then for key, value in pairs(fields) do row[key] = clean(value) end end
        row.k = kind; row.t = t; row.cb = c.cb; row.kid = c.kid; row.key = c.note; row.kch = c.ch
        if c.t and t then row.dt = t - c.t end
        if c.from then row.from_cb = c.from end
        seq = seq + 1; row.s = seq
        head = head % cap + 1
        if count < cap then count = count + 1 else dropped = dropped + 1 end
        ring[head] = row; dirty = true
        if cfg.echo and okJson then pcall(function() print("FVT " .. json.encode(row)) end) end
        return row
    end

    local function voiceKey(id)
        if id == nil then return nil end
        return voiceKeys[tostring(id)]
    end
    local function remember(id)
        if voiceKeyCount >= 8192 then voiceKeys = {}; voiceKeyCount = 0; record("voice_map_reset") end
        nextVoice = nextVoice + 1
        voiceKeys[tostring(id)] = nextVoice; voiceKeyCount = voiceKeyCount + 1
        return nextVoice
    end
    local function forget(id)
        local key = id ~= nil and tostring(id) or nil
        if key and voiceKeys[key] then voiceKeys[key] = nil; voiceKeyCount = voiceKeyCount - 1 end
    end
    local function roleFor(layer)
        if type(layer) == "number" and cfg.layer_roles then return cfg.layer_roles[tostring(layer)] end
        return nil
    end
    local function layerText(layer)
        if type(layer) == "number" then return layer end
        return clean(layer)
    end

    -- Traced API. Calls pass straight through; only the bookkeeping is added.
    local function wrapApi()
        raw.playNote, raw.postEvent, raw.releaseVoice = playNote, postEvent, releaseVoice
        raw.changeTune, raw.fade, raw.fadein, raw.fadeout = changeTune, fade, fadein, fadeout
        raw.spawn, raw.run, raw.wait = spawn, run, wait
        raw.waitBeat, raw.waitForRelease = waitBeat, waitForRelease

        if type(raw.playNote) == "function" then
            playNote = function(...)
                local a1, a2, a3, a4, a5 = ...
                local note, vel, dur, layer, ch = a1, a2, a3, a4, a5
                if type(a1) == "table" then
                    note = a1.note or a1[1]; vel = a1.vel or a1.velocity or a1[2]
                    dur = a1.duration or a1[3]; layer = a1.layer or a1[4]; ch = a1.channel or a1[5]
                end
                inApi = true
                local ok, id = pcall(raw.playNote, ...)
                inApi = false
                if not ok then error(id, 0) end
                if id ~= nil then
                    record("voice_start", {v=remember(id), rid=tostring(id), via="playNote", note=note, vel=vel,
                        dur=dur == nil and -1 or dur, layer=layerText(layer), vch=ch, role=roleFor(layer)})
                else
                    record("voice_fail", {via="playNote", note=note, dur=dur == nil and -1 or dur, layer=layerText(layer)})
                end
                return id
            end
        end
        if type(raw.postEvent) == "function" then
            postEvent = function(e, ...)
                if inApi then return raw.postEvent(e, ...) end
                local c = ctx()
                local kind = type(e) == "table" and e.type or nil
                if kind == 128 then
                    local v = voiceKey(e.id)
                    record("voice_release", {v=v, rid=tostring(e.id), via=c.event == e and "forward_off" or "post_off",
                        note=e.note})
                    forget(e.id)
                end
                local id = raw.postEvent(e, ...)
                if kind == 144 then
                    local vid = id ~= nil and id or e.id
                    local forward = c.event == e
                    record("voice_start", {v=vid ~= nil and remember(vid) or nil, rid=tostring(vid),
                        via=forward and "forward" or "postEvent", note=e.note, vel=e.velocity,
                        dur=type(e.duration) == "number" and e.duration or (forward and -1 or 0),
                        layer=layerText(e.layer), vch=e.channel, role=roleFor(e.layer)})
                end
                return id
            end
        end
        if type(raw.releaseVoice) == "function" then
            releaseVoice = function(id, ...)
                local v = voiceKey(id)
                inApi = true
                local ok, result = pcall(raw.releaseVoice, id, ...)
                inApi = false
                if not ok then error(result, 0) end
                record("voice_release", {v=v, rid=tostring(id), via="releaseVoice", existed=result})
                forget(id)
                return result
            end
        end
        if type(raw.changeTune) == "function" then
            changeTune = function(id, shift, relative, ...)
                record("tune", {v=voiceKey(id), shift=shift, relative=relative})
                return raw.changeTune(id, shift, relative, ...)
            end
        end
        for _, name in ipairs({"fade", "fadein", "fadeout"}) do
            local original = raw[name]
            if type(original) == "function" then
                _G[name] = function(id, a, b, c, ...)
                    record("fade", {fn=name, v=voiceKey(id), a1=a, a2=b, a3=c})
                    return original(id, a, b, c, ...)
                end
            end
        end
        for _, name in ipairs({"spawn", "run"}) do
            local original = raw[name]
            if type(original) == "function" then
                _G[name] = function(fn, ...)
                    local parent = ctx()
                    local child = {cb=name, kid=parent.kid, note=parent.note, ch=parent.ch, t=now(), from=parent.cb}
                    -- spawn may defer the task (Falcon does) or run it until its first wait: either way the
                    -- caller continues in its own context.
                    local a, b = original(function(...) setCtx(child); return fn(...) end, ...)
                    setCtx(parent)
                    return a, b
                end
            end
        end
        for _, name in ipairs({"wait", "waitBeat", "waitForRelease"}) do
            local original = raw[name]
            if type(original) == "function" then
                _G[name] = function(...)
                    local mine = current
                    local a, b = original(...)
                    current = mine
                    return a, b
                end
            end
        end
    end

    local function snapshot()
        local events = {}
        local first = count < cap and 1 or head % cap + 1
        for i = 0, count - 1 do events[#events + 1] = ring[(first - 1 + i) % cap + 1] end
        local okRate, rate = pcall(getSamplingRate)
        return {format=FVT.format, name=cfg.name, seq=seq, dropped=dropped, capacity=cap,
            sample_rate=okRate and rate or nil, written=now(), save_error=saveError, events=events}
    end

    function FVT.flush()
        if saving or not cfg.path or type(saveData) ~= "function" then return false end
        dirty = false; saving = true
        local ok, err = pcall(saveData, snapshot(), cfg.path, function(task)
            saving = false
            -- The task is userdata in Falcon (tostring on it raises); read the field defensively.
            local okField, success = pcall(function() return task.success end)
            if okField and success == false then saveError = "saveData failed" end
        end)
        if not ok then saving = false; saveError = tostring(err) end
        return ok
    end

    local function flushLoop()
        flushing = true
        while true do
            raw.wait(cfg.flush_ms)
            if dirty and cfg.enabled then FVT.flush() end
        end
    end

    local function keyContext(e, cb)
        local ch = e.channel or 1
        local slot = ch * 128 + (e.note or 0)
        if cb == "onNote" then
            nextKid = nextKid + 1
            local queue = held[slot] or {}
            held[slot] = queue; queue[#queue + 1] = nextKid
            return {cb=cb, kid=nextKid, note=e.note, ch=ch, t=now(), event=e}
        end
        local queue = held[slot]
        local kid = queue and table.remove(queue, 1) or nil
        return {cb=cb, kid=kid, note=e.note, ch=ch, t=now(), event=e}
    end

    local function traced(cb, fn, e, ...)
        local previous = ctx()
        local c
        if cb == "onNote" or cb == "onRelease" then
            c = keyContext(e, cb)
            setCtx(c)
            record(cb == "onNote" and "key_on" or "key_off",
                {note=e.note, vel=e.velocity, ch=e.channel or 1, rid=tostring(e.id)})
        else
            c = {cb=cb, kid=previous.kid, note=previous.note, ch=type(e) == "table" and e.channel or nil, t=now(),
                event=e}
            setCtx(c)
            if cb == "onController" and type(e) == "table" and (e.controller == 64 or cfg.all_controllers) then
                record("cc", {cc=e.controller, value=e.value, ch=e.channel or 1})
            elseif cb == "onTransport" then
                record("transport", {playing=e})
            end
        end
        -- No pcall: callbacks may wait(), and Lua 5.1 cannot yield across pcall.
        local a, b, c2, d
        if fn then a, b, c2, d = fn(e, ...)
        elseif type(e) == "table" and postEvent then postEvent(e) end
        setCtx(previous)
        return a, b, c2, d
    end

    local callbackTypes = {[144]="onNote", [128]="onRelease", [176]="onController"}

    function FVT.install()
        if FVT.installed then return end
        FVT.installed = true
        local userEvent = rawget(_G, "onEvent")
        if type(userEvent) == "function" then
            onEvent = function(e, ...) return traced(callbackTypes[e.type] or "onEvent", userEvent, e, ...) end
        else
            local userNote, userRelease, userController = rawget(_G, "onNote"), rawget(_G, "onRelease"), rawget(_G, "onController")
            onNote = function(e, ...) return traced("onNote", userNote, e, ...) end
            onRelease = function(e, ...) return traced("onRelease", userRelease, e, ...) end
            onController = function(e, ...) return traced("onController", userController, e, ...) end
        end
        local userTransport = rawget(_G, "onTransport")
        onTransport = function(playing, ...)
            local previous = ctx()
            setCtx({cb="onTransport", t=now()})
            record("transport", {playing=playing})
            local result
            if userTransport then result = userTransport(playing, ...) end
            setCtx(previous)
            return result
        end
        local userInit = rawget(_G, "onInit")
        onInit = function(...)
            if cfg.path and type(raw.spawn) == "function" and not flushing then raw.spawn(flushLoop) end
            local previous = ctx()
            setCtx({cb="onInit", t=now()})
            record("init", {name=cfg.name})
            local result
            if userInit then result = userInit(...) end
            setCtx(previous)
            return result
        end
    end

    -- Decision reports. Call them where the script actually decides.
    local function fieldsOf(extra)
        local fields = {}
        if type(extra) == "table" then for key, value in pairs(extra) do fields[key] = value end end
        return fields
    end
    function FVT.legato(triggered, reason, extra)
        local f = fieldsOf(extra); f.triggered = triggered and true or false; f.reason = reason
        return record("legato", f)
    end
    function FVT.envelope(id, restarted, reason, extra)
        local f = fieldsOf(extra); f.v = voiceKey(id); f.restarted = restarted and true or false; f.reason = reason
        return record("envelope", f)
    end
    function FVT.pending(state, extra)
        local f = fieldsOf(extra); f.state = state
        return record("pending", f)
    end
    function FVT.owner(id, role, extra)
        local f = fieldsOf(extra); f.v = voiceKey(id); f.role = role
        return record("owner", f)
    end
    function FVT.mark(label, extra)
        local f = fieldsOf(extra); f.label = label
        return record("mark", f)
    end
    function FVT.event(kind, extra)
        local f = fieldsOf(extra); f.kind = kind
        return record("custom", f)
    end
    function FVT.key() local c = ctx(); return c.kid, c.note end
    function FVT.voice(id) return voiceKey(id) end
    function FVT.status()
        return {seq=seq, count=count, dropped=dropped, installed=FVT.installed == true, flushing=flushing,
            save_error=saveError}
    end
    function FVT.enable(on) cfg.enabled = on and true or false end
    FVT._snapshot = snapshot

    wrapApi()
end
